import{_ as t,o,c as a,a2 as r}from"./chunks/framework.hw3Av5Vn.js";const s="/llamatron/assets/arp_editor.V3KGDPBC.svg",d="/llamatron/assets/offsets_editor.5Ru3e7vO.svg",m=JSON.parse('{"title":"Arpeggiator","description":"","frontmatter":{},"headers":[],"relativePath":"generators/ARPEGGIATOR.md","filePath":"generators/ARPEGGIATOR.md"}'),n={name:"generators/ARPEGGIATOR.md"};function h(i,e,c,p,g,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="arpeggiator" tabindex="-1">Arpeggiator <a class="header-anchor" href="#arpeggiator" aria-label="Permalink to &quot;Arpeggiator&quot;">​</a></h1><p>An arpeggiator plays each chord one note at a time, and keeps going for as long as the chord lasts. Rests pass through unchanged. Single notes do too, unless the arpeggiator has offsets or an octave range, which let one note make a melody. Like every generator, it is put to work through a chain, as <a href="./../GENERATORS">Generators</a> describes.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><img src="'+s+'" alt="An arpeggiator&#39;s settings"></p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Name</td><td><code>Enter</code> renames the arpeggiator, and every chain using it follows.</td></tr><tr><td>Step</td><td>How long each note of the chord plays: <code>(pattern)</code>, the step size of the pattern each clip plays, which a new arpeggiator starts with, or a time from the list every time setting shares. <code>Bksp</code> goes back to <code>(pattern)</code>.</td></tr><tr><td>Order</td><td><code>up</code> or <code>down</code> by pitch, <code>up_down</code>, <code>down_up</code>, or <code>random</code>.</td></tr><tr><td>Octave range</td><td>Plays the chord again in up to 4 octaves, from 1, which is the chord alone.</td></tr><tr><td>Octave jump</td><td><code>after chord</code> plays the whole chord before moving up an octave, so C E G becomes C E G C E G; <code>after each note</code> plays each note in every octave first, so it becomes C C E E G G.</td></tr><tr><td>Offsets</td><td>The arpeggiator&#39;s own steps, as on the Elektron Monomachine. <code>Enter</code> edits them, and <code>Bksp</code> removes them.</td></tr><tr><td>Seed</td><td>The seed for <code>random</code>. <code>Bksp</code> goes back to the song&#39;s seed.</td></tr><tr><td>AX+= per note to DX+= per note</td><td>How much every note the arpeggiator plays adds to that register, or takes from it, within the register&#39;s Allowed Inc Max. <code>Bksp</code> sets none. See <a href="./../REGISTERS">Registers</a>.</td></tr><tr><td>Restart</td><td>When it starts over, as <a href="./../GENERATORS#restart">Generators</a> describes.</td></tr></tbody></table><h2 id="offsets" tabindex="-1">Offsets <a class="header-anchor" href="#offsets" aria-label="Permalink to &quot;Offsets&quot;">​</a></h2><p>Offsets are a row of 1 to 16 steps, and the first edit starts them with 8 steps of 0. Each step plays the next note of the chord, moved that many notes along the scale, or by half steps when there is no scale. A blank step is silent, and the next step plays the note it would have played. The steps start again with each chord, so a row whose length doesn&#39;t fit the chord makes a new rhythm against it.</p><p><img src="'+d+'" alt="The offsets editor"></p><p>The offsets editor draws each step&#39;s offset as a bar from a zero line, up for a positive offset and down for a negative one, with the number under each bar. An offset the gauge is too short to reach fills its column and is marked, such as <code>+7▲</code> or <code>-9▼</code>. The cursor&#39;s column is marked at both ends, <code>&lt;&lt;4&gt;&gt;</code> around the step number and <code>&lt;+7▲&gt;</code> around the offset, and a row wider than the screen scrolls sideways, with <code>steps 1-9 ›</code> saying which steps are shown.</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td>Left, Right</td><td>Move along the steps.</td></tr><tr><td>Digits</td><td>Type an offset.</td></tr><tr><td><code>[</code>, <code>]</code> or Up, Down</td><td>Change the offset.</td></tr><tr><td><code>Space</code></td><td>Makes a step silent, or plays it again.</td></tr><tr><td><code>I</code>, <code>D</code></td><td>Insert a step, or remove one.</td></tr><tr><td><code>Tab</code></td><td>Moves to a row for each register, AX+= to DX+=, and back: what each step adds to that register when the arpeggiator reaches it, a silent step too. A register&#39;s row shows once any step adds to it, or while the cursor is on it.</td></tr></tbody></table><h2 id="applying-the-generator" tabindex="-1">Applying the Generator <a class="header-anchor" href="#applying-the-generator" aria-label="Permalink to &quot;Applying the Generator&quot;">​</a></h2><p>Add the arpeggiator to a chain, as <code>arp: name</code>, and give clips that chain. <code>examples/learning/12_sailor_arpeggiator.yml</code> plays one chord through it, in every order and octave setting.</p>',12)])])}const u=t(n,[["render",h]]);export{m as __pageData,u as default};
